import sys

def reverse_bits_brute(n: int) -> int:
    s = format(n, '032b')
    return int(s[::-1], 2)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    print(reverse_bits_brute(n))

import sys

def reverse_bits_opt(n: int) -> int:
    ans = 0
    for i in range(32):
        ans = (ans << 1) | (n & 1)
        n >>= 1
    return ans

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    print(reverse_bits_opt(n))
